vec3 rainbow( in float t)// darkest is purple at pi?
{
    vec3 a = vec3(0.5,0.5,0.5);
    vec3 b = vec3(0.25,0.5,0.5);
    vec3 c = vec3(1.0,1.0,1.0);
    vec3 d = vec3(0.0,0.33,0.67);
    return a + b*cos( 6.28318*(c*t+d) );
}


//math for other color palettes, faster to merge maybe?
vec3 pal( in float t, in vec3 a, in vec3 b, in vec3 c, in vec3 d )
{
    return a + b*cos( 6.28318*(c*t+d) );
}

vec3 partial_spectrum(in float t)
{
    return pal( t, vec3(0.5,0.5,0.5),vec3(0.5,0.5,0.5),vec3(1.0,0.7,0.4),vec3(0.0,0.15,0.20) );
}

