vec3 gradient_dist( vec3 pos ) { //calc reflect and color
    bool  hit;
    float v[6];
    float dist[6];
    for( int i=ZERO; i<6; i++ )
        if ( POWER == 2)       v[i] = frac_dist_2( pos + delta_LUT[i], hit, dist[i]);
        else if ( POWER == 3)  v[i] = frac_dist_3( pos + delta_LUT[i], hit, dist[i]);
        else v[i] = frac_dist( pos + delta_LUT[i], hit, dist[i]);

	return normalize ( vec3(dist[0] - dist[1], dist[2] - dist[3], dist[4] - dist[5]) );
}

vec3 gradient_color_dist2(vec3 pos, inout vec3 color, float tin)//reflect and color from sums
{
    bool  hit;

    //first compute the reflection vector
    // returns distance to v0, will always be 0..<2.  a-f can be larger    
