        if      ( POWER == 2) v[i] = frac_dist_2(pos + color_step*color_delta_LUT_1[i], hit, dist[i]);
        else if ( POWER == 3) v[i] = frac_dist_3(pos + color_step*color_delta_LUT_1[i], hit, dist[i]);
        else                  v[i] = frac_dist(pos + color_step*color_delta_LUT_1[i], hit, dist[i]);
    }
    // try corners of cube 


