    {
        //reuse gradient on cube faces
        case 0: tin = (v0 + v1 + v2 + v3 + v4 + v5 ) / 6.0;
        break;
        case 1: tin = (v0 + v1 + v2 + v3 + v4 + v5 + tin) / 7.0; 
        break;

        //use color step on cube faces
