        break;
        case 3: tin = (v0 + v1 + v2 + v3 + v4 + v5 + tin) / 7.0; // bright, pinker speckly
        break;
        case 4: tin = (v0 + v1 + v2 + v3  ) / 4.0; // dark... asymetric
        break;
        case 5: tin = (v0 + v1 + v2 + v3 +tin  ) / 5.0; // brighter, purply, too speckly
