        break;
            //these were better when accidentally avg twice
        //case 7:tin = (a+b+c+d+e+f+tin)/7.0/10.; //neat, colors like orig mandelbrot
        case 7:tin = (dist[0]+dist[1]+dist[2]+dist[3]+dist[4]+dist[5]+tin)/7.0/10.; //neat, colors like orig mandelbrot
        break;
