        break;
        //case 9: tin = (a+b+c+d+e+f+tin)/7.0/float(MAX_FRAC_STEPS)*8.; //neat, rainbowy, crazy
        case 9: tin = (dist[0]+dist[1]+dist[2]+dist[3]+dist[4]+dist[5]+tin)/7.0/float(MAX_FRAC_STEPS)*8.; //neat, rainbowy, crazy
        break;

        //I'm using 6 pixels, the centers of the faces of a cube of vol 27
        //AA was using 9 pixels from normal plane

        //case 12: tin = (v0 + v1 + v2 + v3 + v4 + v5 + v6 +v7 +v8 ) / 9.0;    //pretends to be AA, but it's assymetric, neat veins on skull- blob
        //break;
    }


    switch (COL_SET)
    {
        case 1: color = new_color3(PI*tin + PI);  // skull blob C nice  brighter than below, 
        break;
        case 2: color = partial_spectrum(PI*tin/2. + PI);//was +3PI/2
        break;
        case 3: color = partial_spectrum(PI*tin + PI);//was +3PI/2
        break;

        case 4: //color = rainbow(PI*tin/2. + 1.33*PI); //was -PI/4  purple edge
                //color = rainbow(PI*tin/2. - 0.25*PI);// about the same, brighter?
                color = rainbow(PI*tin    - 0.25*PI);// too busy?
        break;
        case 5: color = new_color3(1.*pow(tin+1. ,2.0)+ 3.14-1.);  //kinda boring but I like it
                //very similar to 1
        break;

        //cant get here
        case 6: color =new_color3(0.5*  log(tin) ); //sometimes speckly but i like it
                //color =rainbow(3.14+log(tin));// + -1.* 3.14/4. ); //looks like bad icecream, too busy for many
                //color =rainbow(10.*log(tin+1.));// + -1.* 3.14/4. ); //looks like bad icecream
