// o is location of ?
bool ray_marching( vec3 o, vec3 dir, inout float depth, inout vec3 n, inout vec3 col ) {
    //adjust t to mid depth?
    float t =0.;
    bool hit = false;
    float sum;
    float dist, min_dist=999.;
    for ( int i = 0; i < MAX_RAY_STEPS; i++ ) {  //i was 128, is distance z to compute shape?
        vec3 v = o + dir * t; //actually faster than incemental!
        if      (POWER==2) sum = frac_dist_2( v, hit, dist );
        else if (POWER==3) sum = frac_dist_3( v, hit, dist );
        else               sum = frac_dist( v, hit, dist );  //returns sum, hit, distance is 0 for hit, .125  to .125+(max-n)/2
        min_dist = min(dist, min_dist);
        if (( t > depth ) || ( hit)) // if I hit the fractal or the back wall
            break;
        t += RAY_STEP*dist;
    }


    if(COL_SET == 6) //Buddhabrot/Ganesh/Melinda Green. misses are used here too
    {
        float lum;
        SHININESS = 5.0; // too much shine ruins the effect
        SHINE_MIX = 0.6; // .25 cloudy  .5 kinda is too, the 3 colors are equally bright. not always
        n = gradient_dist( o + dir * t); //sum is 0..2, dist for miss almost always max at back wall.
        // dist is 0.125 + 0.5 * float( (MAX_FRAC_STEPS-n)*(MAX_FRAC_STEPS-n))/float(MAX_FRAC_STEPS) ; 
        // 0 for hit. for misss: return a minimum of .125
        //dist max is .125+0.5*max_steps   The more steps it made, the closer it was so smaller distance 

        if (hit) lum = 0.;
        else  lum = (min_dist - 0.125)*2.0/float(MAX_FRAC_STEPS); // lum 0 closest 1 farthest
        col=mix(vec3(0,0,0), col, 1.-lum*lum);   //lower fade, auras
        return true;
    }


    //if no hit then pos is likely at back wall, dist is max, sum is > thresh(2)
    if (!hit) return false; //tells shader to draw background if I didn't hit fractal

    depth = t; //returns this

    if (COL_SET == 0) // if no color used
        {
        SHININESS = 1.0; //1 brighter 100 darker
        SHINE_MIX = 1.0; //no color so make it shiney like silver
        // add reflection NO color
        //n =( gradient( o + dir * t ) ); //frac v4 made it darker? only made sense with dist
        //n = ( gradient_float_hits( o + dir * t ) );//this one is brighter, also faster!
        n = gradient_dist( o + dir * t);//, col, sum ); //the gradient of this pixel
    }

    else if (COL_SET > 0 && COL_SET != 6)
    {
        SHININESS = 1.0;  //1 brighter 100 darker
        SHINE_MIX = 0.5; //amount of glare seen instead of color

        // add reflection and "smoothed" color  dark+bandy on oct w/ 0.02 grad
        //n = gradient_color( o + dir * t, col, sum ); //shine and smoother colors hair faster than above?!?!?
        //a little more sensible, bandy on octo
        //n = gradient_color_float_hits( o + dir * t, col, sum ); //same speed but uses float version, darker

        //n = gradient_color_dist( o + dir * t, col ); //the gradient of this pixel

        //n = gradient_color_dist( o + dir * t, col, sum );//29.1fps    14.9 uglyish
        n = gradient_color_dist2( o + dir * t, col, sum ); //28.9       14.8
        //(vec3 pos, inout vec3 color, float tin)
    }

    #ifdef fog2
    col=mix(BKGD_COLOR, col, clamp((2.+eye_z)/(t*t),0.0,1.0));
    #endif

    //depth, n, col are returned as well
    return true;
}




